### Enhancement 5: Trauma-Based Camera Shake System

```javascript
class CameraShakeSystem {
  constructor() {
    this.intensity = 0;
    this.decayRate = 2.0; // Exponential decay constant
    this.maxIntensity = 0.5;
  }

  addTrauma(impactVelocity) {
    const traumaAmount = Math.min(impactVelocity * 0.1, this.maxIntensity);
    this.intensity = Math.min(this.intensity + traumaAmount, this.maxIntensity);

    // Scale shake based on enemy size
    if (enemySize === 'boss') this.intensity *= 2.5;
  }

  update(dt) {
    this.intensity *= Math.exp(-this.decayRate * dt);

    if (this.intensity > 0.01) {
      camera.position.x += random() * this.intensity * dt;
      camera.position.y += random() * this.intensity * dt * 0.5;
    }
  }
}
```

### Enhancement 6: Hit-Stop / Frame-Freeze System

```javascript
class HitStopSystem {
  constructor() {
    this.hitStopTime = 0;
    this.totalHitStop = 0;
    this.active = false;
  }

  triggerHitStop(enemySize) {
    const hitStopDuration = hitStopTable[enemySize]; // Small: 5ms, Boss: 200ms

    if (hitStopDuration > 0) {
      this.hitStopTime = performance.now();
      this.totalHitStop = hitStopDuration;
      this.active = true;

      // Visual feedback - screen flash
      document.body.classList.add('screen-flash');
      setTimeout(() => document.body.classList.remove('screen-flash'), hitStopDuration);
    }
  }

  getDeltaMultiplier() {
    if (!this.active) return 1.0;

    const elapsed = performance.now() - this.hitStopTime;
    if (elapsed >= this.totalHitStop) {
      this.active = false;
      return 1.0;
    }

    // Gradual recovery curve
    return Math.max(0, 1 - (elapsed / this.totalHitStop));
  }
}
```

### Enhancement 7: Projectile Motion Trails

```javascript
// Trail system using line segments with fade
class ProjectileTrail {
  constructor(projectile) {
    this.trailPoints = [];
    this.maxTrailLength = 20;

    // Create trail geometry
    const points = new Array(this.maxTrailLength).fill(0).map(() => 
      new THREE.Vector3()
    );
    this.geometry = new THREE.BufferGeometry();
    this.geometry.setAttribute('position', new THREE.Float32BufferAttribute(points, 3));

    // Trail material with transparency gradient
    this.material = new THREE.LineBasicMaterial({
      color: projectile.color,
      transparent: true,
      opacity: 0.7
    });
  }

  update(projectile) {
    // Add current position to trail
    this.trailPoints.push(projectile.position.clone());

    if (this.trailPoints.length > this.maxTrailLength) {
      this.trailPoints.shift(); // Remove oldest point
    }

    // Update buffer with new points and fade old ones
    const positions = this.geometry.attributes.position.array;
    for (let i = 0; i < this.trailPoints.length; i++) {
      const age = i / this.maxTrailLength;
      const alpha = Math.max(0, 1 - age);

      positions[i * 3] = this.trailPoints[i].x;
      positions[i * 3 + 1] = this.trailPoints[i].y;
      positions[i * 3 + 2] = this.trailPoints[i].z;
    }

    this.geometry.attributes.position.needsUpdate = true;
  }
}
```

### Enhancement 8: Shockwave Impact Rings

```javascript
class ShockwaveRing {
  constructor(position, intensity) {
    // Create ring geometry - torus with inner radius
    const ringGeometry = new THREE.TorusGeometry(0.5, 0.1, 16, 32);

    this.ring = new THREE.Mesh(ringGeometry, new THREE.MeshStandardMaterial({
      color: '#00FFFF', // Cyan shockwave
      emissive: '#00FFFF',
      transparent: true,
      opacity: 0.8
    }));

    this.ring.position.copy(position);
    this.expansionRate = intensity * 2;
    this.age = 0;
    this.maxAge = 1.0; // Ring lifetime

    scene.add(this.ring);
  }

  update(dt) {
    this.age += dt / this.maxAge;

    // Expand ring based on age
    const scale = 1 + this.age * this.expansionRate;
    this.ring.scale.set(scale, scale, scale);

    // Fade opacity over time
    this.ring.material.opacity = Math.max(0, 1 - this.age);

    if (this.age >= 1) {
      this.dispose();
      return true; // Ring expired
    }
    return false;
  }

  dispose() {
    scene.remove(this.ring);
    this.ring.geometry.dispose();
    this.ring.material.dispose();
  }
}
```

### Enhancement 9: Floating 3D Score Text Popups

```javascript
class ScoreTextPopup {
  constructor(position, scoreValue) {
    // Create text geometry using Three.js FontLoader (procedural font)
    const font = new THREE.Font({
      family: 'Arial',
      size: 12,
      weight: 'bold'
    });

    this.textMesh = new THREE.Mesh(
      new THREE.TextGeometry(scoreValue.toString(), {
        font: font,
        height: 0.5,
        depth: 0.3,
        bevelSize: 0.1
      }),
      new THREE.MeshStandardMaterial({
        color: '#FFD700', // Gold color for score text
        emissive: '#FFD700',
        emissiveIntensity: 0.5
      })
    );

    this.textMesh.position.copy(position);
    this.velocity = new THREE.Vector3(
      random(-2, 2), // Slight horizontal drift
      random(5, 15), // Upward motion
      random(-2, 2)
    );

    scene.add(this.textMesh);
  }

  update(dt) {
    this.textMesh.position.add(this.velocity.clone().multiplyScalar(dt));

    // Slow down upward velocity (gravity effect)
    this.velocity.y -= 0.5 * dt;

    return false; // Never auto-destroy - wait for fade complete
  }
}
```

### Enhancement 10: Boss Fight System

```javascript
class BossSystem {
  constructor(level) {
    this.boss = null;
    this.bossHealth = level * 500; // Scales with difficulty

    if (level % 3 === 0 && level > 1) {
      this.spawnBoss();
    }
  }

  spawnBoss() {
    const bossGeometry = new THREE.BoxGeometry(8, 6, 4);

    this.boss = new BossEntity({
      position: new THREE.Vector3(0, -50, 0),
      health: this.bossHealth,
      damagePerShot: 25,
      attackPattern: 'zigzag', // Complex movement pattern

      // Boss-specific abilities
      specialAbilities: [
        { type: 'shield', duration: 3 },
        { type: 'rapid_fire', duration: 2 },
        { type: 'minion_spawn', count: 4 }
      ]
    });

    scene.add(this.boss);
  }

  update(dt) {
    if (!this.boss || this.boss.health <= 0) return;

    // Execute boss AI pattern
    this.boss.executeAttackPattern(dt);

    // Trigger special abilities based on health thresholds
    const healthPercent = this.boss.health / this.bossHealth;

    if (healthPercent === 0.75 || healthPercent === 0.25) {
      this.boss.triggerSpecialAbility();
    }
  }
}
```

### Enhancement 11: Power-up Drop System

```javascript
class PowerUpSystem {
  constructor() {
    this.powerups = [];

    // Define power-up types and effects
    this.types = {
      SHIELD: { duration: 5, color: '#00FF00', effect: 'invulnerability' },
      RAPID_FIRE: { duration: 3, color: '#FF0000', effect: 'double_fire_rate' },
      WIDE_SHOT: { duration: 4, color: '#0000FF', effect: 'spread_shot' }
    };

    // Power-up drop rate (percentage)
    this.dropRate = 0.15; // 15% chance per enemy kill

    // Create power-up pool for reuse
    this.pool = new ObjectPool(this.types.length * 10, () => {
      return new PowerUpEntity();
    });
  }

  tryDropPowerup(enemyPosition) {
    if (Math.random() > this.dropRate) return null;

    const powerType = randomChoice(Object.keys(this.types));
    const powerup = this.pool.acquire();

    powerup.initialize({
      position: enemyPosition,
      type: powerType,
      duration: this.types[powerType].duration
    });

    this.powerups.push(powerup);
    return powerup;
  }

  update(dt) {
    // Process all active power-ups
    for (let i = this.powerups.length - 1; i >= 0; i--) {
      const powerup = this.powerups[i];

      if (!powerup.update(dt)) {
        this.pool.release(powerup);
        this.powerups.splice(i, 1);
      }
    }
  }
}
```

### Enhancement 12: Dynamic Procedural Music System

```javascript
class ProceduralMusicSystem {
  constructor() {
    this.audioContext = new AudioContext();

    // Musical parameters for Space Invaders theme
    this.baseNotes = [440, 554, 660]; // A4, C#5, E5 - A major triad

    // Intensity levels (0-1 scale)
    this.intensity = 0.3;

    // Procedural music generation using Web Audio API oscillators
    this.musicNodes = [];

    // Start procedural music loop
    this.startMusic();
  }

  startMusic() {
    const oscillator = this.audioContext.createOscillator();
    oscillator.type = 'sawtooth';

    // Connect to gain node for volume control
    const gainNode = this.audioContext.createGain();
    gainNode.gain.value = this.intensity * 0.3;

    oscillator.connect(gainNode);
    gainNode.connect(this.audioContext.destination);

    oscillator.start();

    // Modulate frequency based on game state
    setInterval(() => {
      const noteIndex = Math.floor(Math.random() * this.baseNotes.length);
      oscillator.frequency.value = this.baseNotes[noteIndex] * (1 + this.intensity * 0.2);
    }, 500);

    this.musicNodes.push({ oscillator, gainNode });
  }

  updateIntensity(enemyCount, totalEnemies) {
    // Increase intensity as enemies decrease (more tension)
    const enemyRatio = enemyCount / totalEnemies;
    this.intensity = Math.max(0.1, 1 - enemyRatio);

    // Update all music nodes
    this.musicNodes.forEach(node => {
      node.gainNode.gain.value = this.intensity * 0.3;
    });
  }
}
```

