class ProceduralMusicSystem {
  constructor() {
    this.audioContext = new AudioContext();

    // Musical parameters for Space Invaders theme
    this.baseNotes = [440, 554, 660]; // A4, C#5, E5 - A major triad

    // Intensity levels (0-1 scale)
    this.intensity = 0.3;

    // Procedural music generation using Web Audio API oscillators
    this.musicNodes = [];

    // Start procedural music loop
    this.startMusic();
  }

  startMusic() {
    const oscillator = this.audioContext.createOscillator();
    oscillator.type = 'sawtooth';

    // Connect to gain node for volume control
    const gainNode = this.audioContext.createGain();
    gainNode.gain.value = this.intensity * 0.3;

    oscillator.connect(gainNode);
    gainNode.connect(this.audioContext.destination);

    oscillator.start();

    // Modulate frequency based on game state
    setInterval(() => {
      const noteIndex = Math.floor(Math.random() * this.baseNotes.length);
      oscillator.frequency.value = this.baseNotes[noteIndex] * (1 + this.intensity * 0.2);
    }, 500);

    this.musicNodes.push({ oscillator, gainNode });
  }

  updateIntensity(enemyCount, totalEnemies) {
    // Increase intensity as enemies decrease (more tension)
    const enemyRatio = enemyCount / totalEnemies;
    this.intensity = Math.max(0.1, 1 - enemyRatio);

    // Update all music nodes
    this.musicNodes.forEach(node => {
      node.gainNode.gain.value = this.intensity * 0.3;
    });
  }
}
